begin;

create temporary table question_seed (
  collection_slug text not null,
  slug text not null,
  title text not null,
  problem_statement text not null,
  difficulty text not null,
  topic_tags text[] not null,
  constraints jsonb not null,
  examples jsonb not null,
  starter_code_by_language jsonb not null,
  points integer not null
) on commit drop;

insert into question_seed
select * from jsonb_to_recordset($seed$
[{"collection_slug":"javascript-core-challenges","slug":"reconcile-inventory","title":"Reconcile Inventory Snapshots","problem_statement":"Implement reconcileInventory(warehouse, incoming) for two arrays of {sku, quantity} records. Add quantities for matching SKUs, retain warehouse SKU order, then append newly encountered incoming SKUs in their first-seen order. Ignore records with an empty/non-string SKU or a non-negative-integer violation; do not mutate either input.","difficulty":"Medium","topic_tags":["Maps","Inventory","Validation"],"constraints":["0 <= warehouse.length + incoming.length <= 100000","A valid quantity is a non-negative integer"],"examples":[{"input":"warehouse=[{\"sku\":\"pen\",\"quantity\":4},{\"sku\":\"pad\",\"quantity\":2}], incoming=[{\"sku\":\"pen\",\"quantity\":3},{\"sku\":\"clip\",\"quantity\":5}]","output":"[{\"sku\":\"pen\",\"quantity\":7},{\"sku\":\"pad\",\"quantity\":2},{\"sku\":\"clip\",\"quantity\":5}]"},{"input":"warehouse=[{\"sku\":\"x\",\"quantity\":1}], incoming=[{\"sku\":\"\",\"quantity\":9},{\"sku\":\"x\",\"quantity\":-1}]","output":"[{\"sku\":\"x\",\"quantity\":1}]"}],"starter_code_by_language":{"JavaScript":"function reconcileInventory(warehouse, incoming) {\n  // Return reconciled SKU quantities without mutating either array.\n  return [];\n}","Python":"def reconcile_inventory(warehouse, incoming):\n    # Return reconciled SKU quantities without mutating either list.\n    return []"},"points":150},{"collection_slug":"javascript-core-challenges","slug":"parse-price-cents","title":"Parse a Price into Cents","problem_statement":"Implement parsePriceCents(text) for a trimmed decimal price with an optional leading dollar sign and zero, one, or two fractional digits. Return integer cents, preserving exact decimal meaning; reject grouping separators, signs, exponent notation, more than two decimals, and values beyond 1,000,000 dollars by returning null.","difficulty":"Medium","topic_tags":["Parsing","Money","Validation"],"constraints":["text.length <= 40","Accepted price is between 0 and 1000000 inclusive"],"examples":[{"input":"\"$18.07\"","output":"1807"},{"input":"\"3.456\"","output":"null"}],"starter_code_by_language":{"JavaScript":"function parsePriceCents(text) {\n  // Parse a valid decimal price exactly into cents.\n  return null;\n}","Python":"def parse_price_cents(text):\n    # Parse a valid decimal price exactly into cents.\n    return None"},"points":150},{"collection_slug":"javascript-core-challenges","slug":"merge-query-parameters","title":"Merge URL Query Parameters","problem_statement":"Implement mergeQueryParameters(url, updates). Parse the URL with the WHATWG URL API, apply updates to its query string, delete a parameter when its update is null, and replace all previous values when the update is a string or number. Preserve unrelated parameters and the URL fragment; return null for an invalid URL.","difficulty":"Medium","topic_tags":["URL","Web APIs"],"constraints":["url is an absolute URL","updates is a plain object with string keys and string, number, or null values"],"examples":[{"input":"url=\"https://shop.test/items?tag=old&page=1#top\", updates={tag:\"new\",page:2}","output":"https://shop.test/items?tag=new&page=2#top"},{"input":"url=\"https://api.test/v1?debug=1\", updates={debug:null,q:\"red apple\"}","output":"https://api.test/v1?q=red+apple"}],"starter_code_by_language":{"JavaScript":"function mergeQueryParameters(url, updates) {\n  // Return the updated absolute URL or null when invalid.\n  return null;\n}","Python":"def merge_query_parameters(url, updates):\n    # Return the updated absolute URL or None when invalid.\n    return None"},"points":150},{"collection_slug":"javascript-core-challenges","slug":"parse-csv-record","title":"Parse One CSV Record","problem_statement":"Implement parseCsvRecord(row) for one CSV record. Commas separate unquoted fields; a quoted field may contain commas, and doubled quotes inside it represent one quote. Return null for an unmatched quote or characters after a closing quote other than a comma. Preserve empty fields, including a final empty field.","difficulty":"Medium","topic_tags":["Strings","Parsing","State Machines"],"constraints":["0 <= row.length <= 100000","A quoted field must begin at the start of a field"],"examples":[{"input":"a,\"b,c\",\"say \"\"hi\"\"\"","output":"[\"a\",\"b,c\",\"say \\\"hi\\\"\"]"},{"input":"x,,","output":"[\"x\",\"\",\"\"]"}],"starter_code_by_language":{"JavaScript":"function parseCsvRecord(row) {\n  // Return parsed fields, or null for malformed quoting.\n  return null;\n}","Python":"def parse_csv_record(row):\n    # Return parsed fields, or None for malformed quoting.\n    return None"},"points":150},{"collection_slug":"javascript-core-challenges","slug":"stable-sort-by-deadline","title":"Stably Sort Jobs by Deadline","problem_statement":"Implement stableSortByDeadline(jobs) for jobs with string id and optional ISO timestamp deadline. Return a new array ordered by ascending valid deadline; equal deadlines retain input order, and missing or invalid deadlines appear last in their original relative order. Never mutate the input.","difficulty":"Medium","topic_tags":["Sorting","Dates","Stability"],"constraints":["0 <= jobs.length <= 100000","Valid deadlines use lexicographically sortable UTC ISO-8601 strings"],"examples":[{"input":"[{\"id\":\"a\",\"deadline\":\"2025-03-02T00:00:00Z\"},{\"id\":\"b\",\"deadline\":\"2025-03-01T00:00:00Z\"},{\"id\":\"c\"}]","output":"[\"b\",\"a\",\"c\"]"},{"input":"[{\"id\":\"a\",\"deadline\":\"2025-03-01T00:00:00Z\"},{\"id\":\"b\",\"deadline\":\"2025-03-01T00:00:00Z\"}]","output":"[\"a\",\"b\"]"}],"starter_code_by_language":{"JavaScript":"function stableSortByDeadline(jobs) {\n  // Return a stable sorted copy; place invalid deadlines last.\n  return [];\n}","Python":"def stable_sort_by_deadline(jobs):\n    # Return a stable sorted copy; place invalid deadlines last.\n    return []"},"points":150},{"collection_slug":"javascript-core-challenges","slug":"apply-object-patch","title":"Apply Ordered Object Patch Operations","problem_statement":"Implement applyObjectPatch(source, operations) on a shallow plain object copy. A set operation assigns its value to key; a remove operation deletes key. Apply operations in order, and return null if any operation has an unknown type or a non-string key. The source must remain unchanged.","difficulty":"Medium","topic_tags":["Objects","Patch Semantics","Immutability"],"constraints":["0 <= operations.length <= 10000","Each operation is set or remove and has a string key"],"examples":[{"input":"source={\"name\":\"A\",\"active\":true}, operations=[{type:\"set\",key:\"name\",value:\"B\"},{type:\"remove\",key:\"active\"}]","output":"{\"name\":\"B\"}"},{"input":"source={\"x\":1}, operations=[{type:\"noop\",key:\"x\"}]","output":"null"}],"starter_code_by_language":{"JavaScript":"function applyObjectPatch(source, operations) {\n  // Apply validated operations to a shallow copy.\n  return null;\n}","Python":"def apply_object_patch(source, operations):\n    # Apply validated operations to a shallow copy.\n    return None"},"points":150},{"collection_slug":"javascript-core-challenges","slug":"rate-limit-arrivals","title":"Accept Requests Under a Sliding Limit","problem_statement":"Implement acceptRateLimited(timestamps, windowMs, limit). Scan non-decreasing arrival timestamps; accept an arrival exactly when fewer than limit previously accepted arrivals lie in the inclusive interval [time-windowMs,time]. Rejected arrivals do not consume capacity. Return one boolean per arrival.","difficulty":"Hard","topic_tags":["Sliding Window","Rate Limiting"],"constraints":["timestamps are non-negative integers in non-decreasing order","windowMs is a non-negative integer and limit is positive"],"examples":[{"input":"timestamps=[0,1,2,10], windowMs=5, limit=2","output":"[true,true,false,true]"},{"input":"timestamps=[1,1,1], windowMs=0, limit=1","output":"[true,false,false]"}],"starter_code_by_language":{"JavaScript":"function acceptRateLimited(timestamps, windowMs, limit) {\n  // Return an acceptance decision for each arrival.\n  return [];\n}","Python":"def accept_rate_limited(timestamps, window_ms, limit):\n    # Return an acceptance decision for each arrival.\n    return []"},"points":200},{"collection_slug":"javascript-core-challenges","slug":"extract-route-parameters","title":"Extract and Decode Route Parameters","problem_statement":"Implement extractRouteParameters(template, path). A whole template segment beginning with ':' names a parameter; return an object mapping names to decodeURIComponent-decoded path segments. Return null for segment-count mismatch, empty or duplicate names, empty values, or malformed percent escapes.","difficulty":"Medium","topic_tags":["Routing","URL Decoding"],"constraints":["Each path has at most 100 segments","Literal path segments must match exactly"],"examples":[{"input":"template=\"/users/:id/files/:file\", path=\"/users/u%201/files/a.txt\"","output":"{\"id\":\"u 1\",\"file\":\"a.txt\"}"},{"input":"template=\"/items/:id\", path=\"/items/%ZZ\"","output":"null"}],"starter_code_by_language":{"JavaScript":"function extractRouteParameters(template, path) {\n  // Return decoded route parameters, or null for a mismatch.\n  return null;\n}","Python":"def extract_route_parameters(template, path):\n    # Return decoded route parameters, or None for a mismatch.\n    return None"},"points":150},{"collection_slug":"javascript-core-challenges","slug":"summarize-payment-status","title":"Summarize Payments by Status","problem_statement":"Implement summarizePayments(payments). For records with a non-empty string status and finite numeric amount, return a status-keyed object containing count and total. Ignore invalid records and do not coerce numeric strings; a status first seen later is added in its first-seen order.","difficulty":"Medium","topic_tags":["Aggregation","API Data"],"constraints":["0 <= payments.length <= 100000","Only finite JavaScript number amounts qualify"],"examples":[{"input":"[{\"status\":\"paid\",\"amount\":12},{\"status\":\"refunded\",\"amount\":3},{\"status\":\"paid\",\"amount\":5}]","output":"{\"paid\":{\"count\":2,\"total\":17},\"refunded\":{\"count\":1,\"total\":3}}"},{"input":"[{\"status\":\"paid\",\"amount\":\"8\"},{\"status\":\"\",\"amount\":4}]","output":"{}"}],"starter_code_by_language":{"JavaScript":"function summarizePayments(payments) {\n  // Return per-status valid payment counts and totals.\n  return {};\n}","Python":"def summarize_payments(payments):\n    # Return per-status valid payment counts and totals.\n    return {}"},"points":150},{"collection_slug":"javascript-core-challenges","slug":"group-activity-by-date","title":"Group Activity by Calendar Date","problem_statement":"Implement groupActivityByDate(events). Group each event with a valid UTC timestamp into a YYYY-MM-DD key and append its id in input order. Reject impossible calendar dates and malformed timestamps; return an object whose date keys are ordered chronologically.","difficulty":"Medium","topic_tags":["Dates","Grouping"],"constraints":["0 <= events.length <= 100000","Timestamp format is YYYY-MM-DDTHH:mm:ssZ"],"examples":[{"input":"[{\"id\":\"a\",\"at\":\"2024-02-29T10:00:00Z\"},{\"id\":\"b\",\"at\":\"2024-02-28T11:00:00Z\"},{\"id\":\"c\",\"at\":\"2024-02-29T12:00:00Z\"}]","output":"{\"2024-02-28\":[\"b\"],\"2024-02-29\":[\"a\",\"c\"]}"},{"input":"[{\"id\":\"x\",\"at\":\"2023-02-29T00:00:00Z\"}]","output":"{}"}],"starter_code_by_language":{"JavaScript":"function groupActivityByDate(events) {\n  // Return date-keyed event ID arrays in chronological key order.\n  return {};\n}","Python":"def group_activity_by_date(events):\n    # Return date-keyed event ID arrays in chronological key order.\n    return {}"},"points":150},{"collection_slug":"javascript-core-challenges","slug":"merge-time-intervals","title":"Merge Time Intervals","problem_statement":"Implement mergeTimeIntervals(intervals) for finite numeric [start,end] pairs with start <= end. Return sorted merged intervals; overlapping intervals and intervals touching at an endpoint combine. Produce new pairs and do not mutate input.","difficulty":"Medium","topic_tags":["Intervals","Sorting"],"constraints":["0 <= intervals.length <= 100000","Endpoints are finite numbers"],"examples":[{"input":"[[1,3],[2,6],[8,10],[10,12]]","output":"[[1,6],[8,12]]"},{"input":"[[4,4],[1,2]]","output":"[[1,2],[4,4]]"}],"starter_code_by_language":{"JavaScript":"function mergeTimeIntervals(intervals) {\n  // Return sorted, merged interval pairs.\n  return [];\n}","Python":"def merge_time_intervals(intervals):\n    # Return sorted, merged interval pairs.\n    return []"},"points":150},{"collection_slug":"javascript-core-challenges","slug":"rank-products-by-sales","title":"Rank Products by Sales","problem_statement":"Implement rankProducts(records, limit). Aggregate non-negative integer units by non-empty string productId, ignoring invalid records, then return up to limit {productId,units} entries ordered by units descending and productId ascending to break ties. Do not mutate records.","difficulty":"Medium","topic_tags":["Maps","Ranking","Aggregation"],"constraints":["0 <= records.length <= 100000","limit is a non-negative integer"],"examples":[{"input":"records=[{productId:\"b\",units:2},{productId:\"a\",units:3},{productId:\"b\",units:2}], limit=2","output":"[{\"productId\":\"b\",\"units\":4},{\"productId\":\"a\",\"units\":3}]"},{"input":"records=[{productId:\"x\",units:-2}], limit=5","output":"[]"}],"starter_code_by_language":{"JavaScript":"function rankProducts(records, limit) {\n  // Aggregate valid units and return the top products.\n  return [];\n}","Python":"def rank_products(records, limit):\n    # Aggregate valid units and return the top products.\n    return []"},"points":150},{"collection_slug":"javascript-core-challenges","slug":"build-comment-tree","title":"Build a Comment Reply Tree","problem_statement":"Implement buildCommentTree(comments) for unique {id,parentId,text} records where parentId is null or another id. Return root comments with nested children arrays in original input order; attach descendants only when their parent exists. Discard every cycle member and any descendant whose parent chain enters a cycle.","difficulty":"Hard","topic_tags":["Trees","Data Transformation"],"constraints":["0 <= comments.length <= 50000","IDs are unique strings"],"examples":[{"input":"[{\"id\":\"a\",\"parentId\":null,\"text\":\"Root\"},{\"id\":\"b\",\"parentId\":\"a\",\"text\":\"Reply\"},{\"id\":\"c\",\"parentId\":null,\"text\":\"Other\"}]","output":"[{\"id\":\"a\",\"parentId\":null,\"text\":\"Root\",\"children\":[{\"id\":\"b\",\"parentId\":\"a\",\"text\":\"Reply\",\"children\":[]}]},{\"id\":\"c\",\"parentId\":null,\"text\":\"Other\",\"children\":[]}]"},{"input":"[{\"id\":\"x\",\"parentId\":\"missing\",\"text\":\"Orphan\"}]","output":"[{\"id\":\"x\",\"parentId\":\"missing\",\"text\":\"Orphan\",\"children\":[]}]"}],"starter_code_by_language":{"JavaScript":"function buildCommentTree(comments) {\n  // Return nested roots with children arrays.\n  return [];\n}","Python":"def build_comment_tree(comments):\n    # Return nested roots with children arrays.\n    return []"},"points":200},{"collection_slug":"javascript-core-challenges","slug":"dependency-execution-order","title":"Order Tasks by Dependencies","problem_statement":"Implement dependencyExecutionOrder(tasks, dependencies). Each pair [task, prerequisite] requires prerequisite first. Among currently available tasks, always choose the lexicographically smallest. Return null for duplicate task names, unknown dependency names, duplicate dependency pairs, or a cycle.","difficulty":"Hard","topic_tags":["Graphs","Topological Sort"],"constraints":["1 <= tasks.length <= 10000","0 <= dependencies.length <= 50000"],"examples":[{"input":"tasks=[\"write\",\"test\",\"build\"], dependencies=[[\"test\",\"build\"],[\"write\",\"test\"]]","output":"[\"build\",\"test\",\"write\"]"},{"input":"tasks=[\"a\",\"b\"], dependencies=[[\"a\",\"b\"],[\"b\",\"a\"]]","output":"null"}],"starter_code_by_language":{"JavaScript":"function dependencyExecutionOrder(tasks, dependencies) {\n  // Return the lexicographically selected topological order or null.\n  return null;\n}","Python":"def dependency_execution_order(tasks, dependencies):\n    # Return the lexicographically selected topological order or None.\n    return None"},"points":200},{"collection_slug":"javascript-core-challenges","slug":"allocate-discount-cents","title":"Allocate Discount Cents Fairly","problem_statement":"Implement allocateDiscountCents(lineAmounts, discount). Inputs and discount are non-negative integer cents, and discount cannot exceed their sum. Allocate proportionally using floor shares, then distribute remaining cents by descending fractional remainder with lower original index breaking ties. Return allocations summing exactly to discount.","difficulty":"Hard","topic_tags":["Money","Rounding","Arrays"],"constraints":["0 <= lineAmounts.length <= 10000","Positive discount requires positive total line amount"],"examples":[{"input":"lineAmounts=[500,300,200], discount=300","output":"[150,90,60]"},{"input":"lineAmounts=[1,1,1], discount=2","output":"[1,1,0]"}],"starter_code_by_language":{"JavaScript":"function allocateDiscountCents(lineAmounts, discount) {\n  // Return integer-cent allocations using largest remainders.\n  return [];\n}","Python":"def allocate_discount_cents(line_amounts, discount):\n    # Return integer-cent allocations using largest remainders.\n    return []"},"points":200},{"collection_slug":"javascript-core-challenges","slug":"calculate-retry-delays","title":"Calculate Capped Retry Delays","problem_statement":"Implement calculateRetryDelays({baseMs,retries,maxMs,jitter}). Return one delay per retry: double the prior delay up to maxMs, then add jitter[i] and clamp again to maxMs. The first delay is baseMs plus jitter[0]. A missing jitter entry is zero; inputs are validated by the constraints.","difficulty":"Medium","topic_tags":["Async","Retry Policy"],"constraints":["0 <= retries <= 20","1 <= baseMs <= maxMs <= 1000000000 and jitter entries are non-negative integers"],"examples":[{"input":"{\"baseMs\":100,\"retries\":4,\"maxMs\":500,\"jitter\":[0,10,0,20]}","output":"[100,210,420,500]"},{"input":"{\"baseMs\":50,\"retries\":0,\"maxMs\":1000,\"jitter\":[]}","output":"[]"}],"starter_code_by_language":{"JavaScript":"function calculateRetryDelays({ baseMs, retries, maxMs, jitter }) {\n  // Return the capped delay sequence.\n  return [];\n}","Python":"def calculate_retry_delays(base_ms, retries, max_ms, jitter):\n    # Return the capped delay sequence.\n    return []"},"points":150},{"collection_slug":"javascript-core-challenges","slug":"normalize-http-headers","title":"Normalize HTTP Headers","problem_statement":"Implement normalizeHttpHeaders(headers) for a list of [name,value] pairs. Lowercase names, trim values, and combine repeated names by joining values with \", \" in original order. Ignore pairs whose name is empty or whose value is not a string.","difficulty":"Easy","topic_tags":["HTTP","Normalization"],"constraints":["0 <= headers.length <= 10000","Header names are ASCII strings"],"examples":[{"input":"[[\"Content-Type\",\" application/json \"],[\"X-Mode\",\"fast\"],[\"x-mode\",\"safe\"]]","output":"{\"content-type\":\"application/json\",\"x-mode\":\"fast, safe\"}"},{"input":"[[\"\",\"x\"],[\"Accept\",\"text/plain\"]]","output":"{\"accept\":\"text/plain\"}"}],"starter_code_by_language":{"JavaScript":"function normalizeHttpHeaders(headers) {\n  // Return lowercase, trimmed, combined header values.\n  return {};\n}","Python":"def normalize_http_headers(headers):\n    # Return lowercase, trimmed, combined header values.\n    return {}"},"points":100},{"collection_slug":"javascript-core-challenges","slug":"validate-cursor-page","title":"Validate and Decode a Cursor Page","problem_statement":"Implement decodeCursorPage(token). The token is base64url-encoded UTF-8 JSON with exactly {id,createdAt}; id must be non-empty and createdAt must be a real ISO UTC timestamp. Return the decoded object or null for bad base64url, invalid JSON, wrong fields, or invalid date.","difficulty":"Hard","topic_tags":["Base64url","API Validation"],"constraints":["token.length <= 4096","createdAt format is YYYY-MM-DDTHH:mm:ssZ with a valid calendar date"],"examples":[{"input":"\"eyJpZCI6ImM3IiwiY3JlYXRlZEF0IjoiMjAyNC0wMi0yOVQxMDowMDowMFoifQ\"","output":"{\"id\":\"c7\",\"createdAt\":\"2024-02-29T10:00:00Z\"}"},{"input":"\"eyJpZCI6IiJ9\"","output":"null"}],"starter_code_by_language":{"JavaScript":"function decodeCursorPage(token) {\n  // Decode, validate, and return the cursor payload or null.\n  return null;\n}","Python":"def decode_cursor_page(token):\n    # Decode, validate, and return the cursor payload or None.\n    return None"},"points":200},{"collection_slug":"javascript-core-challenges","slug":"compare-semver-versions","title":"Compare Semantic Version Precedence","problem_statement":"Implement compareSemverVersions(a,b) for versions MAJOR.MINOR.PATCH with optional dot-separated prerelease identifiers. Compare numeric core parts numerically; a release outranks its prerelease; numeric prerelease identifiers compare numerically and rank below non-numeric identifiers. Return -1, 0, or 1, or null for malformed versions.","difficulty":"Hard","topic_tags":["Strings","Versioning"],"constraints":["Core components are non-negative safe integers","Build metadata is not accepted"],"examples":[{"input":"\"1.2.0-rc.2\", \"1.2.0-rc.10\"","output":"-1"},{"input":"\"2.0.0\", \"2.0.0-beta\"","output":"1"}],"starter_code_by_language":{"JavaScript":"function compareSemverVersions(a, b) {\n  // Return -1, 0, 1, or null for invalid version text.\n  return null;\n}","Python":"def compare_semver_versions(a, b):\n    # Return -1, 0, 1, or None for invalid version text.\n    return None"},"points":200},{"collection_slug":"javascript-core-challenges","slug":"build-offset-pagination","title":"Build an Offset Pagination Envelope","problem_statement":"Implement buildOffsetPagination(items,total,page,pageSize). Page is one-based; clamp pageSize to 1..100 and page to at least 1. Return the current slice and metadata {page,pageSize,totalPages,hasNext,hasPrevious}; totalPages is zero when total is zero and page is clamped to at most totalPages when nonempty.","difficulty":"Medium","topic_tags":["Pagination","API Responses"],"constraints":["items.length <= pageSize before clamping","total is a non-negative integer and items contains the requested page slice"],"examples":[{"input":"items=[\"d\",\"e\"], total=12, page=2, pageSize=5","output":"{\"items\":[\"d\",\"e\"],\"page\":2,\"pageSize\":5,\"totalPages\":3,\"hasNext\":true,\"hasPrevious\":true}"},{"input":"items=[], total=0, page=8, pageSize=0","output":"{\"items\":[],\"page\":1,\"pageSize\":1,\"totalPages\":0,\"hasNext\":false,\"hasPrevious\":false}"}],"starter_code_by_language":{"JavaScript":"function buildOffsetPagination(items, total, page, pageSize) {\n  // Return the page items and consistent pagination metadata.\n  return {};\n}","Python":"def build_offset_pagination(items, total, page, page_size):\n    # Return the page items and consistent pagination metadata.\n    return {}"},"points":150}]
$seed$::jsonb) as seed(
  collection_slug text, slug text, title text, problem_statement text, difficulty text,
  topic_tags text[], constraints jsonb, examples jsonb, starter_code_by_language jsonb, points integer
);

do $$
declare seed_count integer; distinct_count integer;
begin
  select count(*), count(distinct slug) into seed_count, distinct_count from question_seed;
  if seed_count <> 20 or distinct_count <> 20 then
    raise exception 'Expected exactly 20 unique JavaScript questions; got % records and % slugs', seed_count, distinct_count;
  end if;
  if exists (
    select 1 from question_seed
    where char_length(btrim(problem_statement)) < 100
       or jsonb_array_length(constraints) < 2 or jsonb_array_length(examples) < 2
       or jsonb_object_length(starter_code_by_language) <> 2
       or title ilike '%placeholder%' or problem_statement ilike '%placeholder%'
       or not (starter_code_by_language ?& array['JavaScript','Python'])
       or starter_code_by_language->>'JavaScript' ilike '%TODO%'
       or starter_code_by_language->>'Python' ilike '%TODO%'
       or starter_code_by_language->>'JavaScript' not like '%function %'
       or starter_code_by_language->>'Python' not like '%def %'
  ) then raise exception 'JavaScript question is incomplete or lacks a supported starter'; end if;
  if (select count(distinct title) from question_seed) <> 20
     or (select count(distinct problem_statement) from question_seed) <> 20 then
    raise exception 'JavaScript question titles and statements must be distinct';
  end if;
  if exists (
    select 1 from question_seed s
    where not exists (
      select 1 from jsonb_array_elements(s.examples) as x(item)
      where x.item->>'output' not in ('null','[]','{}','')
    )
  ) then raise exception 'Each JavaScript question needs a substantive example output'; end if;
  if exists (select 1 from question_seed
    where slug in ('first-unique-character','chunk-array','stable-deduplicate','flatten-one-level','group-objects-by-key','interleave-two-arrays','sum-object-property')) then
    raise exception 'JavaScript seed overlaps an existing question slug';
  end if;
  if not exists (select 1 from public.coding_test_sets where slug='javascript-core-challenges') then
    raise exception 'Missing collection javascript-core-challenges';
  end if;
end $$;

with collection as (
  select id from public.coding_test_sets where slug='javascript-core-challenges'
), ordered_seed as (
  select s.*, coalesce((select max(q.question_order) from public.coding_questions q
    join collection c on c.id=q.collection_id),0) + row_number() over (order by s.slug) as question_order
  from question_seed s
)
insert into public.coding_questions (
  collection_id, slug, title, problem_statement, difficulty, topic_tags, constraints,
  examples, starter_code_by_language, points, publication_status, question_order
)
select c.id, s.slug, s.title, s.problem_statement, s.difficulty, s.topic_tags, s.constraints,
  s.examples, s.starter_code_by_language, s.points, 'published', s.question_order
from ordered_seed s cross join collection c
on conflict (collection_id, slug) do nothing;

insert into public.coding_test_cases (question_id, case_order, test_input, expected_output, visibility)
select q.id, e.ordinality::integer, e.item->>'input', e.item->>'output', 'visible'
from question_seed s
join public.coding_test_sets c on c.slug=s.collection_slug
join public.coding_questions q on q.collection_id=c.id and q.slug=s.slug
cross join lateral jsonb_array_elements(s.examples) with ordinality as e(item, ordinality)
on conflict (question_id, case_order) do nothing;

commit;
